(* [comment removed for export] *)
Lemma w4s32_round : forall (Q : machine_state -> Prop) (RNG : footprint) (mm : amem) (F : bvmap 5 word) (fc : bv 32)
    (x1 gp tp x6 x7 x9 x10 x12 x13 x14 x16 x19 x20 x23 x24 x26 x27 x29 x30 x31 : word)
    (P DT4 DBL DBH DST dcap tl mtl PE SS n SBL SBH S2 S3 L2 PTR BITS PP : Z) (cells : list deltX1) (obuf : list Z)
    (w224 : word),
  w4s32_ctx RNG mm P DT4 DBL DBH DST dcap tl mtl PE SS n SBL SBH S2 S3 cells -> mem_inv asegs mm ->
  x1_table_ok cells tl -> u8arr asegs mm DST (map (Z_to_bv 8) obuf) -> zlen obuf = dcap ->
  rw_cells asegs mm (P + 224) [C8 w224] ->
  n < 2^26 -> KXGoM.apart SS n P 496 -> KXGoM.apart DST dcap SS n ->
  SS <= S2 -> S2 + L2 <= SS + n -> 8 <= S2 -> S2 + 16 <= 2^47 ->
  S2 <= PTR -> (PTR = S2 \/ PTR + 8 <= S2 + L2) -> 0 <= BITS <= 64 ->
  DST <= PP -> PP <= PE -> DST + 4 <= PE -> PE <= DST + dcap -> DST + dcap < 2^47 -> 0 <= S3 < 2^64 -> 1 <= mtl <= 12 ->
  (forall (mm' : amem) (PTR' B' : Z) (cw y6 y13 y14 y29 y30 y31 : word),
     munch [(DST, DST + dcap); (P + 224, P + 232)] mm mm' -> wmono asegs mm mm' -> mem_inv asegs mm' ->
     (exists obuf', u8arr asegs mm' DST (map (Z_to_bv 8) obuf') /\ zlen obuf' = dcap) ->
     rw_cells asegs mm' (P + 224) [C8 cw] ->
     S2 <= PTR' -> (PTR' = S2 \/ PTR' + 8 <= S2 + L2) -> 0 <= B' <= 64 -> PP + 4 <= PE ->
     evtF asegs RNG Q (MS (mkR x1 (Z_to_bv 64 P) gp tp (Z_to_bv 64 (PE + -3)) y6 x7 (Z_to_bv 64 S3) x9 x10 (Z_to_bv 64 (PP
          + 4)) x12 y13 y14 (Z_to_bv 64 (PP + 4)) x16 (Z_to_bv 64 64) (Z_to_bv 64 S2) x19 x20 (Z_to_bv 64 B') (Z_to_bv
          64 DT4) x23 x24 (Z_to_bv 64 PTR') x26 x27 (Z_to_bv 64 (64 - tl)) y29 y30 y31) F (Z_to_bv 64 0x91e84) fc None
          mm' (seg_rom asegs))) ->
  (forall (mm' : amem) (B' : Z) (cw c224 y6 y12 y13 y14 y25 y30 : word),
     munch [(DST, DST + dcap); (P + 224, P + 232)] mm mm' -> wmono asegs mm mm' -> mem_inv asegs mm' ->
     (exists obuf', u8arr asegs mm' DST (map (Z_to_bv 8) obuf') /\ zlen obuf' = dcap) ->
     rw_cells asegs mm' (P + 224) [C8 c224] -> 0 <= B' <= 64 ->
     evtF asegs RNG Q (MS (mkR x1 (Z_to_bv 64 P) gp tp (Z_to_bv 64 (PE + -3)) y6 x7 (Z_to_bv 64 S3) x9 x10 (Z_to_bv 64 PP)
          y12 y13 y14 (Z_to_bv 64 PP) x16 (Z_to_bv 64 64) (Z_to_bv 64 S2) x19 x20 (Z_to_bv 64 (tl + 256 * mtl))
          (Z_to_bv 64 DT4) x23 x24 y25 x26 x27 (Z_to_bv 64 B') (Z_to_bv 64 PE) y30 cw) F (Z_to_bv 64 0x9232c) fc None
          mm' (seg_rom asegs))) ->
  evtF asegs RNG Q (MS (mkR x1 (Z_to_bv 64 P) gp tp (Z_to_bv 64 (PE + -3)) x6 x7 (Z_to_bv 64 S3) x9 x10 (Z_to_bv 64 PP)
      x12 x13 x14 (Z_to_bv 64 PP) x16 (Z_to_bv 64 64) (Z_to_bv 64 S2) x19 x20 (Z_to_bv 64 BITS) (Z_to_bv 64 DT4) x23
      x24 (Z_to_bv 64 PTR) x26 x27 (Z_to_bv 64 (64 - tl)) x29 x30 x31) F (Z_to_bv 64 0x91e84) fc None mm (seg_rom
      asegs)).
