Lemma w4s32_tailf : forall (k : nat) (Q : machine_state -> Prop) (RNG : footprint) (mm : amem) (F : bvmap 5 word) (fc : bv 32)
    (x1 gp tp x5 x6 x7 x9 x10 x12 x13 x14 x16 x18 x19 x20 x23 x24 x25 x26 x27 x30 : word)
    (P DT4 DBL DBH DST dcap tl PP PE B C S3 DESC : Z) (cells : list deltX1) (obuf : list Z),
  Z.of_nat k = PE - PP -> 1 <= PE - PP -> PE <= DST + dcap -> DST <= PP -> 0 <= B -> B + 12 * (PE - PP) <= 2^40 ->
  w4s1_dctx RNG mm P DT4 DBL DBH DST dcap tl -> mem_inv asegs mm -> x1_table_ok cells tl ->
  bytes_at asegs mm DT4 (firstn (Z.to_nat (2 * 2^tl)) (x1_bytes cells)) ->
  u8arr asegs mm DST (map (Z_to_bv 8) obuf) -> zlen obuf = dcap ->
  rw_cells asegs mm (P + 136) [C8 (Z_to_bv 64 2147450880)] -> 0 <= C < 2^64 ->
  (forall (mm' : amem) (B' : Z) (y5 y6 y14 y30 : word),
     munch [(DST, DST + dcap)] mm mm' -> wmono asegs mm mm' -> mem_inv asegs mm' ->
     (exists obuf', u8arr asegs mm' DST (map (Z_to_bv 8) obuf') /\ zlen obuf' = dcap) ->
     evtF asegs RNG Q (MS (mkR x1 (Z_to_bv 64 P) gp tp y5 y6 x7 (Z_to_bv 64 S3) x9 x10 (Z_to_bv 64 PE) x12 (Z_to_bv 64 PE)
          y14 (Z_to_bv 64 PE) x16 (Z_to_bv 64 (64 - tl)) x18 x19 x20 (Z_to_bv 64 DESC) (Z_to_bv 64 DT4) x23 x24
          (Z_to_bv 64 B') x26 x27 (Z_to_bv 64 B') (Z_to_bv 64 PE) y30 (Z_to_bv 64 C)) F (Z_to_bv 64 0x923d8) fc None
          mm' (seg_rom asegs))) ->
  evtF asegs RNG Q (MS (mkR x1 (Z_to_bv 64 P) gp tp x5 x6 x7 (Z_to_bv 64 S3) x9 x10 (Z_to_bv 64 PP) x12 x13 x14 (Z_to_bv
      64 PP) x16 (Z_to_bv 64 (64 - tl)) x18 x19 x20 (Z_to_bv 64 DESC) (Z_to_bv 64 DT4) x23 x24 x25 x26 x27 (Z_to_bv 64
