Lemma w4s32_all : forall (Q : machine_state -> Prop) (RNG : footprint) (mm : amem) (F : bvmap 5 word) (fc : bv 32)
    (x1 gp tp x5 x6 x7 x9 x10 x11 x12 x13 x14 x16 x17 x19 x20 x23 x24 x26 x27 x28 x29 x30 x31 : word)
    (P DT4 DBL DBH DST dcap tl mtl PE SS n SBL SBH S2 S3 L2 PTR BITS PP : Z) (cells : list deltX1) (obuf : list Z)
    (w224 : word),
  w4s32_ctx RNG mm P DT4 DBL DBH DST dcap tl mtl PE SS n SBL SBH S2 S3 cells -> mem_inv asegs mm ->
  x1_table_ok cells tl -> u8arr asegs mm DST (map (Z_to_bv 8) obuf) -> zlen obuf = dcap ->
  rw_cells asegs mm (P + 224) [C8 w224] ->
  n < 2^26 -> KXGoM.apart SS n P 496 -> KXGoM.apart DST dcap SS n -> 1 <= n ->
  SS <= S2 -> S2 + L2 <= SS + n -> 8 <= S2 -> S2 + 16 <= 2^47 ->
  S2 <= PTR -> (PTR = S2 \/ PTR + 8 <= S2 + L2) -> 0 <= BITS < 2^31 ->
  DST <= PP <= PE -> PE <= DST + dcap -> DST + dcap < 2^47 -> 1 <= dcap <= 2^32 -> 0 <= S3 < 2^64 -> 1 <= mtl <= 12 ->
  (forall (mm' : amem) (c224 y5 y6 y11 y12 y13 y14 y15 y17 y25 y28 y29 y30 y31 : word),
