     evtF asegs RNG Q (MS (mkR x1 (Z_to_bv 64 P) gp tp y5 y6 x7 (Z_to_bv 64 S3) x9 x10 y11 y12 y13 y14 y15 x16 y17 (Z_to_bv
          64 S2) x19 x20 (Z_to_bv 64 (tl + 256 * mtl)) (Z_to_bv 64 DT4) x23 x24 y25 x26 x27 y28 y29 y30 y31) F
          (Z_to_bv 64 0x923d8) fc None mm' (seg_rom asegs))) ->
  evtF asegs RNG Q (MS (mkR x1 (Z_to_bv 64 P) gp tp x5 x6 x7 (Z_to_bv 64 S3) x9 x10 x11 x12 x13 x14 (Z_to_bv 64 PP) x16
      x17 (Z_to_bv 64 S2) x19 x20 (Z_to_bv 64 BITS) (Z_to_bv 64 DT4) x23 x24 (Z_to_bv 64 PTR) x26 x27 x28 x29 x30 x31)
      F (Z_to_bv 64 0x91e48) fc None mm (seg_rom asegs)).
